// migrate.js - Database migration script
// This script reads SQL files from the ./migrations/ directory and logs each filename it would apply, in order.

const fs = require('fs');
const path = require('path');

// Directory containing migration files
const migrationsDir = './migrations';

// Function to read and list migration files in order
function listMigrations() {
  try {
    // Check if the migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.log(`Migrations directory '${migrationsDir}' does not exist.`);
      return;
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter out non-SQL files and sort them
    const migrationFiles = files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort();

    if (migrationFiles.length === 0) {
      console.log('No SQL migration files found in the migrations directory.');
      return;
    }

    console.log('Migration files to apply (in order):');
    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

  } catch (err) {
    console.error('Error reading migration files:', err.message);
  }
}

// Execute the migration listing
listMigrations();

module.exports = { listMigrations };

