 * and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

// Path to the migrations directory
const migrationsDir = path.join(__dirname, './migrations');

// Get the list of SQL files in the migrations directory
const getMigrationFiles = () => {
  let files;

  try {
    files = fs.readdirSync(migrationsDir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`Error: Migrations directory not found at ${migrationsDir}`);
    } else {
      console.error(`Error reading migrations directory: ${err.message}`);
    }
    process.exit(1);
  }

  // Filter for .sql files and sort them
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort((a, b) => a.localeCompare(b));

  return sqlFiles;
};

// Log the migration files that would be applied
const logMigrations = () => {
  const sqlFiles = getMigrationFiles();

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found.');
  } else {
    console.log('Migration files to be applied (in order):');
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${path.join('./migrations', file)}`);
    });
  }
};

// Execute the migration logging logic
logMigrations();

