#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Directory containing migration files
const MIGRATIONS_DIR = './migrations';

// Function to read and sort migration files
function getMigrationFiles() {
  try {
    // Read the contents of the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter and sort migration files by name
    const migrationFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    return migrationFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

// Function to log migration filenames
function logMigrations(migrationFiles) {
  console.log('Migrations to apply:');
  migrationFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });
}

// Main function
function main() {
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  logMigrations(migrationFiles);
}

main();

